import React, { useState } from 'react';
import { db } from '../dataClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Award, Plus, Users, TrendingUp, Pencil, Search } from 'lucide-react';
import { toast } from 'sonner';

const TIER_COLORS = {
  standard: 'bg-orange-100 text-orange-800',
  silver: 'bg-slate-200 text-slate-800',
  gold: 'bg-yellow-100 text-yellow-800',
  platinum: 'bg-purple-100 text-purple-800'
};

export default function LoyaltyManagement() {
  const queryClient = useQueryClient();
  const [showAddReward, setShowAddReward] = useState(false);
  const [editingMember, setEditingMember] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [newReward, setNewReward] = useState({
    name: '', description: '', points_required: 0,
    tier_requirement: 'standard', reward_type: 'discount', value: 0, available: true
  });

  const { data: rewards = [] } = useQuery({
    queryKey: ['loyalty-rewards'],
    queryFn: () => db.entities.LoyaltyReward.list()
  });

  const { data: loyaltyMembers = [] } = useQuery({
    queryKey: ['loyalty-members'],
    queryFn: () => db.entities.LoyaltyPoints.list('-lifetime_points')
  });

  const { data: guests = [] } = useQuery({
    queryKey: ['guests'],
    queryFn: () => db.entities.Guest.list()
  });

  // Build guest lookup map
  const guestMap = React.useMemo(() => {
    const m = {};
    guests.forEach(g => { m[g.id] = g; });
    return m;
  }, [guests]);

  const createRewardMutation = useMutation({
    mutationFn: (data) => db.entities.LoyaltyReward.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['loyalty-rewards'] });
      setShowAddReward(false);
      setNewReward({ name: '', description: '', points_required: 0, tier_requirement: 'standard', reward_type: 'discount', value: 0, available: true });
      toast.success('Reward created!');
    }
  });

  const toggleRewardMutation = useMutation({
    mutationFn: ({ id, available }) => db.entities.LoyaltyReward.update(id, { available }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['loyalty-rewards'] })
  });

  const updateMemberMutation = useMutation({
    mutationFn: ({ id, guestId, data }) => Promise.all([
      db.entities.LoyaltyPoints.update(id, data),
      guestId ? db.entities.Guest.update(guestId, { loyalty_tier: data.current_tier }) : Promise.resolve()
    ]),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['loyalty-members'] });
      queryClient.invalidateQueries({ queryKey: ['guests'] });
      setEditingMember(null);
      toast.success('Member updated!');
    }
  });

  const stats = {
    totalMembers: loyaltyMembers.length,
    totalPointsIssued: loyaltyMembers.reduce((sum, m) => sum + (m.lifetime_points || 0), 0),
    totalPointsRedeemed: loyaltyMembers.reduce((sum, m) => sum + (m.points_redeemed || 0), 0),
    avgPointsPerMember: loyaltyMembers.length > 0
      ? Math.round(loyaltyMembers.reduce((sum, m) => sum + (m.total_points || 0), 0) / loyaltyMembers.length) : 0
  };

  const filteredMembers = loyaltyMembers.filter(m => {
    const guest = guestMap[m.guest_id];
    if (!guest) return true;
    const name = `${guest.first_name} ${guest.last_name}`.toLowerCase();
    return name.includes(searchTerm.toLowerCase()) || guest.email?.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6">
      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { icon: Users, value: stats.totalMembers, label: 'Total Members', color: 'text-blue-600' },
          { icon: Award, value: stats.totalPointsIssued.toLocaleString(), label: 'Points Issued', color: 'text-purple-600' },
          { icon: TrendingUp, value: stats.totalPointsRedeemed.toLocaleString(), label: 'Points Redeemed', color: 'text-green-600' },
          { icon: Award, value: stats.avgPointsPerMember, label: 'Avg Points/Member', color: 'text-orange-600' }
        ].map(({ icon: Icon, value, label, color }) => (
          <Card key={label}>
            <CardContent className="p-4 text-center">
              <Icon className={`w-8 h-8 mx-auto mb-2 ${color}`} />
              <p className="text-2xl font-bold">{value}</p>
              <p className="text-sm text-slate-600">{label}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <span className="flex items-center gap-2"><Award className="w-6 h-6" /> Loyalty Program Management</span>
            <Button onClick={() => setShowAddReward(!showAddReward)}>
              <Plus className="w-4 h-4 mr-2" /> Add Reward
            </Button>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="members">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="members">Members</TabsTrigger>
              <TabsTrigger value="rewards">Rewards</TabsTrigger>
            </TabsList>

            {/* Members Tab */}
            <TabsContent value="members" className="space-y-4">
              <div className="relative">
                <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                <Input
                  placeholder="Search by name or email..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-9"
                />
              </div>
              <div className="space-y-3">
                {filteredMembers.map(member => {
                  const guest = guestMap[member.guest_id];
                  return (
                    <Card key={member.id}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div className="flex-1">
                            <p className="font-semibold">
                              {guest ? `${guest.first_name} ${guest.last_name}` : `Guest ${member.guest_id?.slice(0, 8)}`}
                            </p>
                            {guest?.email && <p className="text-xs text-slate-500">{guest.email}</p>}
                            <div className="flex items-center gap-2 mt-2 flex-wrap">
                              <Badge className={TIER_COLORS[member.current_tier]}>{member.current_tier}</Badge>
                              <span className="text-sm text-slate-600">
                                {member.total_bookings || 0} bookings • ${(member.total_spent || 0).toFixed(0)} spent
                              </span>
                            </div>
                          </div>
                          <div className="flex items-center gap-3">
                            <div className="text-right">
                              <p className="text-2xl font-bold text-purple-600">{member.total_points || 0}</p>
                              <p className="text-xs text-slate-500">{member.lifetime_points || 0} lifetime</p>
                            </div>
                            <Button size="sm" variant="outline" onClick={() => setEditingMember({ ...member })}>
                              <Pencil className="w-4 h-4" />
                            </Button>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
                {filteredMembers.length === 0 && (
                  <p className="text-center text-slate-500 py-8">No members found</p>
                )}
              </div>
            </TabsContent>

            {/* Rewards Tab */}
            <TabsContent value="rewards" className="space-y-4">
              {showAddReward && (
                <Card>
                  <CardContent className="p-4 space-y-3">
                    <Input placeholder="Reward Name" value={newReward.name}
                      onChange={(e) => setNewReward({ ...newReward, name: e.target.value })} />
                    <Textarea placeholder="Description" value={newReward.description}
                      onChange={(e) => setNewReward({ ...newReward, description: e.target.value })} />
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <Label>Points Required</Label>
                        <Input type="number" value={newReward.points_required}
                          onChange={(e) => setNewReward({ ...newReward, points_required: parseInt(e.target.value) })} />
                      </div>
                      <div>
                        <Label>Value ($)</Label>
                        <Input type="number" value={newReward.value}
                          onChange={(e) => setNewReward({ ...newReward, value: parseFloat(e.target.value) })} />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <Select value={newReward.tier_requirement} onValueChange={(v) => setNewReward({ ...newReward, tier_requirement: v })}>
                        <SelectTrigger><SelectValue /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="standard">Standard</SelectItem>
                          <SelectItem value="silver">Silver</SelectItem>
                          <SelectItem value="gold">Gold</SelectItem>
                          <SelectItem value="platinum">Platinum</SelectItem>
                        </SelectContent>
                      </Select>
                      <Select value={newReward.reward_type} onValueChange={(v) => setNewReward({ ...newReward, reward_type: v })}>
                        <SelectTrigger><SelectValue /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="discount">Discount</SelectItem>
                          <SelectItem value="upgrade">Room Upgrade</SelectItem>
                          <SelectItem value="free_service">Free Service</SelectItem>
                          <SelectItem value="amenity">Amenity</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <Button className="w-full" onClick={() => createRewardMutation.mutate(newReward)}>
                      Create Reward
                    </Button>
                  </CardContent>
                </Card>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {rewards.map(reward => (
                  <Card key={reward.id}>
                    <CardContent className="p-4">
                      <div className="flex justify-between items-start mb-2">
                        <div className="flex-1">
                          <h3 className="font-semibold">{reward.name}</h3>
                          <p className="text-sm text-slate-600 mt-1">{reward.description}</p>
                        </div>
                        <Button size="sm" variant={reward.available ? 'default' : 'outline'}
                          onClick={() => toggleRewardMutation.mutate({ id: reward.id, available: !reward.available })}>
                          {reward.available ? 'Active' : 'Inactive'}
                        </Button>
                      </div>
                      <div className="flex items-center gap-2 mt-3 flex-wrap">
                        <Badge>{reward.points_required} pts</Badge>
                        <Badge className={TIER_COLORS[reward.tier_requirement]}>{reward.tier_requirement}</Badge>
                        <Badge variant="outline">{reward.reward_type}</Badge>
                        {reward.value > 0 && <Badge variant="outline">${reward.value}</Badge>}
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      {/* Edit Member Dialog */}
      {editingMember && (
        <Dialog open={!!editingMember} onOpenChange={() => setEditingMember(null)}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Edit Loyalty Member</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-2">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Available Points</Label>
                  <Input type="number" value={editingMember.total_points || 0}
                    onChange={(e) => setEditingMember({ ...editingMember, total_points: parseInt(e.target.value) || 0 })} />
                </div>
                <div>
                  <Label>Lifetime Points</Label>
                  <Input type="number" value={editingMember.lifetime_points || 0}
                    onChange={(e) => setEditingMember({ ...editingMember, lifetime_points: parseInt(e.target.value) || 0 })} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Points Redeemed</Label>
                  <Input type="number" value={editingMember.points_redeemed || 0}
                    onChange={(e) => setEditingMember({ ...editingMember, points_redeemed: parseInt(e.target.value) || 0 })} />
                </div>
                <div>
                  <Label>Total Bookings</Label>
                  <Input type="number" value={editingMember.total_bookings || 0}
                    onChange={(e) => setEditingMember({ ...editingMember, total_bookings: parseInt(e.target.value) || 0 })} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Total Spent ($)</Label>
                  <Input type="number" value={editingMember.total_spent || 0}
                    onChange={(e) => setEditingMember({ ...editingMember, total_spent: parseFloat(e.target.value) || 0 })} />
                </div>
                <div>
                  <Label>Loyalty Tier</Label>
                  <Select value={editingMember.current_tier}
                    onValueChange={(v) => setEditingMember({ ...editingMember, current_tier: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="standard">Standard</SelectItem>
                      <SelectItem value="silver">Silver</SelectItem>
                      <SelectItem value="gold">Gold</SelectItem>
                      <SelectItem value="platinum">Platinum</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setEditingMember(null)}>Cancel</Button>
              <Button onClick={() => updateMemberMutation.mutate({
                id: editingMember.id,
                guestId: editingMember.guest_id,
                data: {
                  total_points: editingMember.total_points,
                  lifetime_points: editingMember.lifetime_points,
                  points_redeemed: editingMember.points_redeemed,
                  total_bookings: editingMember.total_bookings,
                  total_spent: editingMember.total_spent,
                  current_tier: editingMember.current_tier
                }
              })}>Save Changes</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { db } from '../dataClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Megaphone, Plus, Sparkles, Send, TrendingUp, Target, Mail } from 'lucide-react';
import { toast } from 'sonner';

export default function MarketingCampaigns() {
  const queryClient = useQueryClient();
  const [showCreateCampaign, setShowCreateCampaign] = useState(false);
  const [showCreateOffer, setShowCreateOffer] = useState(false);
  const [newCampaign, setNewCampaign] = useState({
    name: '',
    description: '',
    campaign_type: 'email',
    target_segment: 'all',
    tier_filter: [],
    status: 'draft'
  });
  const [newOffer, setNewOffer] = useState({
    title: '',
    description: '',
    offer_type: 'discount',
    discount_percentage: 0,
    valid_from: '',
    valid_until: '',
    active: true
  });

  const { data: campaigns = [] } = useQuery({
    queryKey: ['campaigns'],
    queryFn: () => db.entities.Campaign.list('-created_date')
  });

  const { data: offers = [] } = useQuery({
    queryKey: ['offers'],
    queryFn: () => db.entities.Offer.list('-created_date')
  });

  const { data: guests = [] } = useQuery({
    queryKey: ['guests'],
    queryFn: () => db.entities.Guest.list()
  });

  const createCampaignMutation = useMutation({
    mutationFn: (data) => db.entities.Campaign.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['campaigns'] });
      setShowCreateCampaign(false);
      setNewCampaign({ name: '', description: '', campaign_type: 'email', target_segment: 'all', tier_filter: [], status: 'draft' });
      toast.success('Campaign created!');
    }
  });

  const createOfferMutation = useMutation({
    mutationFn: (data) => db.entities.Offer.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['offers'] });
      setShowCreateOffer(false);
      setNewOffer({ title: '', description: '', offer_type: 'discount', discount_percentage: 0, valid_from: '', valid_until: '', active: true });
      toast.success('Offer created!');
    }
  });

  const generateAICampaignMutation = useMutation({
    mutationFn: async ({ segment }) => {
      const response = await db.integrations.Core.InvokeLLM({
        prompt: `Generate a personalized marketing campaign for hotel guests in the "${segment}" segment. 

        Create a compelling campaign with:
        - Campaign name (catchy and relevant)
        - Campaign description
        - Email subject line
        - Email message (personalized and engaging, 2-3 paragraphs)
        - Recommended offer type and discount

        Consider guest preferences, loyalty status, and booking patterns for this segment.`,
        response_json_schema: {
          type: "object",
          properties: {
            campaign_name: { type: "string" },
            campaign_description: { type: "string" },
            email_subject: { type: "string" },
            email_message: { type: "string" },
            offer_type: { type: "string" },
            discount_percentage: { type: "number" }
          }
        }
      });

      return response;
    },
    onSuccess: (data) => {
      setNewCampaign({
        ...newCampaign,
        name: data.campaign_name,
        description: data.campaign_description
      });
      toast.success('AI campaign generated!');
    }
  });

  const launchCampaignMutation = useMutation({
    mutationFn: async (campaign) => {
      let targetGuests = guests.filter(g => g.marketing_opt_in);

      if (campaign.target_segment === 'vip') {
        targetGuests = targetGuests.filter(g => g.vip_status);
      } else if (campaign.target_segment === 'loyalty_tier' && campaign.tier_filter?.length > 0) {
        targetGuests = targetGuests.filter(g => campaign.tier_filter.includes(g.loyalty_tier));
      } else if (campaign.target_segment === 'inactive') {
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        targetGuests = targetGuests.filter(g => 
          !g.last_campaign_date || new Date(g.last_campaign_date) < thirtyDaysAgo
        );
      }

      const offer = campaign.offer_id ? offers.find(o => o.id === campaign.offer_id) : null;

      const notifications = await Promise.all(
        targetGuests.map(async (guest) => {
          const personalizedResponse = await db.integrations.Core.InvokeLLM({
            prompt: `Create a personalized marketing message for ${guest.first_name} ${guest.last_name}, 
            a ${guest.loyalty_tier} tier member. 

            Campaign: ${campaign.name}
            ${offer ? `Offer: ${offer.title} - ${offer.description}` : ''}

            Make it personal, warm, and engaging. Include their name and loyalty status.`,
            response_json_schema: {
              type: "object",
              properties: {
                subject: { type: "string" },
                message: { type: "string" }
              }
            }
          });

          return db.entities.Notification.create({
            guest_id: guest.id,
            campaign_id: campaign.id,
            notification_type: campaign.campaign_type,
            subject: personalizedResponse.subject,
            message: personalizedResponse.message,
            personalized_content: personalizedResponse,
            status: 'sent',
            sent_date: new Date().toISOString()
          });
        })
      );

      await db.entities.Campaign.update(campaign.id, {
        status: 'active',
        total_sent: targetGuests.length,
        start_date: new Date().toISOString()
      });

      await db.entities.AnalyticsData.create({
        metric_type: 'revenue',
        metric_value: targetGuests.length,
        metric_date: new Date().toISOString(),
        domain: 'overall',
        metadata: {
          event: 'campaign_launched',
          campaign_id: campaign.id,
          campaign_name: campaign.name,
          target_segment: campaign.target_segment,
          notifications_sent: targetGuests.length
        }
      });

      return { notifications, targetCount: targetGuests.length };
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries();
      toast.success(`Campaign launched! ${data.targetCount} notifications sent.`);
    }
  });

  const getCampaignStatusColor = (status) => {
    const colors = {
      draft: 'bg-slate-200 text-slate-800',
      scheduled: 'bg-blue-100 text-blue-800',
      active: 'bg-green-100 text-green-800',
      completed: 'bg-purple-100 text-purple-800',
      paused: 'bg-orange-100 text-orange-800'
    };
    return colors[status] || colors.draft;
  };

  const stats = {
    totalCampaigns: campaigns.length,
    activeCampaigns: campaigns.filter(c => c.status === 'active').length,
    totalSent: campaigns.reduce((sum, c) => sum + (c.total_sent || 0), 0),
    avgOpenRate: campaigns.length > 0 
      ? (campaigns.reduce((sum, c) => sum + (c.total_sent > 0 ? (c.total_opened / c.total_sent) * 100 : 0), 0) / campaigns.length).toFixed(1)
      : 0
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4 text-center">
            <Megaphone className="w-8 h-8 mx-auto mb-2 text-blue-600" />
            <p className="text-2xl font-bold">{stats.totalCampaigns}</p>
            <p className="text-sm text-slate-600">Total Campaigns</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <Target className="w-8 h-8 mx-auto mb-2 text-green-600" />
            <p className="text-2xl font-bold">{stats.activeCampaigns}</p>
            <p className="text-sm text-slate-600">Active Campaigns</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <Send className="w-8 h-8 mx-auto mb-2 text-purple-600" />
            <p className="text-2xl font-bold">{stats.totalSent}</p>
            <p className="text-sm text-slate-600">Messages Sent</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <Mail className="w-8 h-8 mx-auto mb-2 text-orange-600" />
            <p className="text-2xl font-bold">{stats.avgOpenRate}%</p>
            <p className="text-sm text-slate-600">Avg Open Rate</p>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <span className="flex items-center gap-2">
              <Megaphone className="w-6 h-6" />
              Marketing Campaigns
            </span>
            <div className="flex gap-2">
              <Button onClick={() => setShowCreateOffer(!showCreateOffer)} variant="outline">
                <Plus className="w-4 h-4 mr-2" />
                New Offer
              </Button>
              <Button onClick={() => setShowCreateCampaign(!showCreateCampaign)}>
                <Plus className="w-4 h-4 mr-2" />
                New Campaign
              </Button>
            </div>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="campaigns">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="campaigns">Campaigns</TabsTrigger>
              <TabsTrigger value="offers">Offers</TabsTrigger>
            </TabsList>

            <TabsContent value="campaigns" className="space-y-4">
              {showCreateCampaign && (
                <Card className="border-2 border-blue-200">
                  <CardContent className="p-4 space-y-4">
                    <div className="flex items-center justify-between">
                      <h3 className="font-semibold">Create New Campaign</h3>
                      <Button 
                        size="sm" 
                        variant="outline"
                        onClick={() => generateAICampaignMutation.mutate({ segment: newCampaign.target_segment })}
                        disabled={generateAICampaignMutation.isPending}
                      >
                        <Sparkles className="w-4 h-4 mr-2" />
                        AI Generate
                      </Button>
                    </div>
                    <Input
                      placeholder="Campaign Name"
                      value={newCampaign.name}
                      onChange={(e) => setNewCampaign({ ...newCampaign, name: e.target.value })}
                    />
                    <Textarea
                      placeholder="Campaign Description"
                      value={newCampaign.description}
                      onChange={(e) => setNewCampaign({ ...newCampaign, description: e.target.value })}
                    />
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <Label>Campaign Type</Label>
                        <Select value={newCampaign.campaign_type} onValueChange={(v) => setNewCampaign({ ...newCampaign, campaign_type: v })}>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="email">Email</SelectItem>
                            <SelectItem value="push_notification">Push Notification</SelectItem>
                            <SelectItem value="sms">SMS</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div>
                        <Label>Target Segment</Label>
                        <Select value={newCampaign.target_segment} onValueChange={(v) => setNewCampaign({ ...newCampaign, target_segment: v })}>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="all">All Guests</SelectItem>
                            <SelectItem value="vip">VIP Only</SelectItem>
                            <SelectItem value="loyalty_tier">By Loyalty Tier</SelectItem>
                            <SelectItem value="inactive">Inactive Guests</SelectItem>
                            <SelectItem value="frequent">Frequent Guests</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <Button className="w-full" onClick={() => createCampaignMutation.mutate(newCampaign)}>
                      Create Campaign
                    </Button>
                  </CardContent>
                </Card>
              )}

              <div className="space-y-3">
                {campaigns.map(campaign => {
                  const openRate = campaign.total_sent > 0 ? ((campaign.total_opened / campaign.total_sent) * 100).toFixed(1) : 0;
                  const conversionRate = campaign.total_sent > 0 ? ((campaign.total_conversions / campaign.total_sent) * 100).toFixed(1) : 0;

                  return (
                    <Card key={campaign.id}>
                      <CardContent className="p-4">
                        <div className="flex items-start justify-between mb-3">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-2">
                              <h3 className="font-semibold">{campaign.name}</h3>
                              <Badge className={getCampaignStatusColor(campaign.status)}>
                                {campaign.status}
                              </Badge>
                              {campaign.ai_generated && (
                                <Badge variant="outline" className="bg-purple-50">
                                  <Sparkles className="w-3 h-3 mr-1" />
                                  AI
                                </Badge>
                              )}
                            </div>
                            <p className="text-sm text-slate-600">{campaign.description}</p>
                            <div className="flex gap-4 mt-2 text-xs text-slate-500">
                              <span>Type: {campaign.campaign_type}</span>
                              <span>Target: {campaign.target_segment}</span>
                            </div>
                          </div>
                          {campaign.status === 'draft' && (
                            <Button 
                              size="sm"
                              onClick={() => launchCampaignMutation.mutate(campaign)}
                              disabled={launchCampaignMutation.isPending}
                            >
                              <Send className="w-4 h-4 mr-2" />
                              Launch
                            </Button>
                          )}
                        </div>

                        {campaign.total_sent > 0 && (
                          <div className="grid grid-cols-3 gap-4 pt-3 border-t">
                            <div>
                              <p className="text-xs text-slate-500">Sent</p>
                              <p className="text-lg font-bold">{campaign.total_sent}</p>
                            </div>
                            <div>
                              <p className="text-xs text-slate-500">Open Rate</p>
                              <p className="text-lg font-bold text-blue-600">{openRate}%</p>
                            </div>
                            <div>
                              <p className="text-xs text-slate-500">Conversions</p>
                              <p className="text-lg font-bold text-green-600">{campaign.total_conversions}</p>
                            </div>
                          </div>
                        )}
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </TabsContent>

            <TabsContent value="offers" className="space-y-4">
              {showCreateOffer && (
                <Card className="border-2 border-blue-200">
                  <CardContent className="p-4 space-y-3">
                    <h3 className="font-semibold">Create New Offer</h3>
                    <Input
                      placeholder="Offer Title"
                      value={newOffer.title}
                      onChange={(e) => setNewOffer({ ...newOffer, title: e.target.value })}
                    />
                    <Textarea
                      placeholder="Offer Description"
                      value={newOffer.description}
                      onChange={(e) => setNewOffer({ ...newOffer, description: e.target.value })}
                    />
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <Label>Offer Type</Label>
                        <Select value={newOffer.offer_type} onValueChange={(v) => setNewOffer({ ...newOffer, offer_type: v })}>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="discount">Discount</SelectItem>
                            <SelectItem value="upgrade">Room Upgrade</SelectItem>
                            <SelectItem value="bonus_points">Bonus Points</SelectItem>
                            <SelectItem value="package">Package Deal</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div>
                        <Label>Discount %</Label>
                        <Input
                          type="number"
                          value={newOffer.discount_percentage}
                          onChange={(e) => setNewOffer({ ...newOffer, discount_percentage: parseFloat(e.target.value) })}
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <Label>Valid From</Label>
                        <Input
                          type="date"
                          value={newOffer.valid_from}
                          onChange={(e) => setNewOffer({ ...newOffer, valid_from: e.target.value })}
                        />
                      </div>
                      <div>
                        <Label>Valid Until</Label>
                        <Input
                          type="date"
                          value={newOffer.valid_until}
                          onChange={(e) => setNewOffer({ ...newOffer, valid_until: e.target.value })}
                        />
                      </div>
                    </div>
                    <Button className="w-full" onClick={() => createOfferMutation.mutate(newOffer)}>
                      Create Offer
                    </Button>
                  </CardContent>
                </Card>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {offers.map(offer => (
                  <Card key={offer.id}>
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between mb-2">
                        <div className="flex-1">
                          <h3 className="font-semibold">{offer.title}</h3>
                          <p className="text-sm text-slate-600 mt-1">{offer.description}</p>
                        </div>
                        <Badge variant={offer.active ? 'default' : 'outline'}>
                          {offer.active ? 'Active' : 'Inactive'}
                        </Badge>
                      </div>
                      <div className="flex items-center gap-2 mt-3">
                        <Badge>{offer.offer_type}</Badge>
                        {offer.discount_percentage > 0 && (
                          <Badge className="bg-green-100 text-green-800">
                            {offer.discount_percentage}% OFF
                          </Badge>
                        )}
                      </div>
                      <div className="text-xs text-slate-500 mt-2">
                        Valid: {new Date(offer.valid_from).toLocaleDateString()} - {new Date(offer.valid_until).toLocaleDateString()}
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/admin/RoomServiceManageme:
import React, { useState } from 'react';
import { db } from '../dataClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { UtensilsCrossed, Plus, CheckCircle2, Clock, Package } from 'lucide-react';
import { toast } from 'sonner';

export default function RoomServiceManagement() {
  const queryClient = useQueryClient();
  const [showAddItem, setShowAddItem] = useState(false);
  const [newItem, setNewItem] = useState({
    name: '',
    category: 'breakfast',
    description: '',
    price: 0,
    preparation_time: 30,
    available: true
  });

  const { data: menuItems = [] } = useQuery({
    queryKey: ['room-service-items'],
    queryFn: () => db.entities.RoomServiceItem.list()
  });

  const { data: orders = [] } = useQuery({
    queryKey: ['room-service-orders'],
    queryFn: () => db.entities.RoomServiceOrder.list('-order_time')
  });

  const createItemMutation = useMutation({
    mutationFn: (data) => db.entities.RoomServiceItem.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['room-service-items'] });
      setShowAddItem(false);
      setNewItem({ name: '', category: 'breakfast', description: '', price: 0, preparation_time: 30, available: true });
      toast.success('Menu item added!');
    }
  });

  const updateOrderMutation = useMutation({
    mutationFn: ({ id, status }) => db.entities.RoomServiceOrder.update(id, { 
      status,
      ...(status === 'delivered' && { delivered_time: new Date().toISOString() })
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['room-service-orders'] });
      toast.success('Order updated!');
    }
  });

  const toggleAvailabilityMutation = useMutation({
    mutationFn: ({ id, available }) => db.entities.RoomServiceItem.update(id, { available }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['room-service-items'] });
    }
  });

  const getStatusColor = (status) => {
    const colors = {
      pending: 'bg-yellow-100 text-yellow-800',
      preparing: 'bg-blue-100 text-blue-800',
      on_the_way: 'bg-purple-100 text-purple-800',
      delivered: 'bg-green-100 text-green-800',
      cancelled: 'bg-red-100 text-red-800'
    };
    return colors[status] || 'bg-slate-100 text-slate-800';
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <span className="flex items-center gap-2">
              <UtensilsCrossed className="w-6 h-6" />
              Room Service Management
            </span>
            <Button onClick={() => setShowAddItem(!showAddItem)}>
              <Plus className="w-4 h-4 mr-2" />
              Add Menu Item
            </Button>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="orders">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="orders">Active Orders</TabsTrigger>
              <TabsTrigger value="menu">Menu Items</TabsTrigger>
            </TabsList>

            <TabsContent value="orders" className="space-y-4">
              {orders.filter(o => o.status !== 'delivered' && o.status !== 'cancelled').map(order => (
                <Card key={order.id}>
                  <CardContent className="p-4">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <Badge className={getStatusColor(order.status)}>{order.status}</Badge>
                        <p className="text-sm text-slate-600 mt-1">
                          Order #{order.id.slice(0, 8)} • ${order.total_amount.toFixed(2)}
                        </p>
                      </div>
                      <Badge variant="outline">
                        <Clock className="w-3 h-3 mr-1" />
                        {new Date(order.order_time).toLocaleTimeString()}
                      </Badge>
                    </div>

                    <div className="space-y-1 mb-3">
                      {order.items.map((item, idx) => (
                        <p key={idx} className="text-sm">
                          {item.quantity}x {item.item_name}
                        </p>
                      ))}
                      {order.special_instructions && (
                        <p className="text-xs text-slate-500 italic mt-2">
                          Note: {order.special_instructions}
                        </p>
                      )}
                    </div>

                    <div className="flex gap-2">
                      {order.status === 'pending' && (
                        <Button size="sm" onClick={() => updateOrderMutation.mutate({ id: order.id, status: 'preparing' })}>
                          Start Preparing
                        </Button>
                      )}
                      {order.status === 'preparing' && (
                        <Button size="sm" onClick={() => updateOrderMutation.mutate({ id: order.id, status: 'on_the_way' })}>
                          Out for Delivery
                        </Button>
                      )}
                      {order.status === 'on_the_way' && (
                        <Button size="sm" onClick={() => updateOrderMutation.mutate({ id: order.id, status: 'delivered' })}>
                          Mark Delivered
                        </Button>
                      )}
                      <Button size="sm" variant="outline" onClick={() => updateOrderMutation.mutate({ id: order.id, status: 'cancelled' })}>
                        Cancel
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </TabsContent>

            <TabsContent value="menu" className="space-y-4">
              {showAddItem && (
                <Card>
                  <CardContent className="p-4 space-y-3">
                    <Input
                      placeholder="Item Name"
                      value={newItem.name}
                      onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
                    />
                    <Select value={newItem.category} onValueChange={(v) => setNewItem({ ...newItem, category: v })}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="breakfast">Breakfast</SelectItem>
                        <SelectItem value="lunch">Lunch</SelectItem>
                        <SelectItem value="dinner">Dinner</SelectItem>
                        <SelectItem value="drinks">Drinks</SelectItem>
                        <SelectItem value="snacks">Snacks</SelectItem>
                        <SelectItem value="desserts">Desserts</SelectItem>
                      </SelectContent>
                    </Select>
                    <Textarea
                      placeholder="Description"
                      value={newItem.description}
                      onChange={(e) => setNewItem({ ...newItem, description: e.target.value })}
                    />
                    <Input
                      type="number"
                      placeholder="Price"
                      value={newItem.price}
                      onChange={(e) => setNewItem({ ...newItem, price: parseFloat(e.target.value) })}
                    />
                    <Button className="w-full" onClick={() => createItemMutation.mutate(newItem)}>
                      Add Item
                    </Button>
                  </CardContent>
                </Card>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {menuItems.map(item => (
                  <Card key={item.id}>
                    <CardContent className="p-4">
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <h3 className="font-semibold">{item.name}</h3>
                          <Badge variant="outline" className="mt-1">{item.category}</Badge>
                          <p className="text-sm text-slate-600 mt-2">{item.description}</p>
                          <p className="text-lg font-bold text-blue-600 mt-2">${item.price}</p>
                        </div>
                        <Button
                          size="sm"
                          variant={item.available ? 'default' : 'outline'}
                          onClick={() => toggleAvailabilityMutation.mutate({ id: item.id, available: !item.available })}
                        >
                          {item.available ? 'Available' : 'Unavailable'}
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/admin/SystemConfiguration:
import React, { useState } from 'react';
import { db } from '../dataClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Building2, ArrowUpDown, Settings } from 'lucide-react';
import { toast } from 'sonner';

export default function SystemConfiguration() {
  const queryClient = useQueryClient();
  const [floorGenConfig, setFloorGenConfig] = useState({ 
    total_floors: 10, 
    parking_floors: 2 
  });
  const [elevatorConfig, setElevatorConfig] = useState({ elevator_name: '', capacity: 10 });
  const [roomGenConfig, setRoomGenConfig] = useState({ 
    start_floor: 1, 
    end_floor: 10, 
    room_type: 'standard', 
    rate_per_night: 150 
  });
  const [parkingConfig, setParkingConfig] = useState({
    level: 'P1',
    spots_per_level: 100
  });

  const { data: floors = [] } = useQuery({
    queryKey: ['floors'],
    queryFn: () => db.entities.Floor.list('floor_number')
  });

  const { data: elevators = [] } = useQuery({
    queryKey: ['elevators'],
    queryFn: () => db.entities.Elevator.list()
  });

  const { data: rooms = [] } = useQuery({
    queryKey: ['rooms'],
    queryFn: () => db.entities.Room.list()
  });

  const { data: parkingSpots = [] } = useQuery({
    queryKey: ['parking-spots'],
    queryFn: () => db.entities.ParkingSpot.list()
  });

  const generateFloorsMutation = useMutation({
    mutationFn: async (config) => {
      const floorsToCreate = [];

      // Create parking floors (negative numbers)
      for (let i = 1; i <= config.parking_floors; i++) {
        const floorNum = -i;
        const exists = floors.some(f => f.floor_number === floorNum);
        if (!exists) {
          floorsToCreate.push({
            floor_number: floorNum,
            floor_name: `Parking Level ${i} (P${i})`,
            floor_type: 'parking',
            access_level: 'guest_only'
          });
        }
      }

      // Create ground floor
      if (!floors.some(f => f.floor_number === 0)) {
        floorsToCreate.push({
          floor_number: 0,
          floor_name: 'Ground Floor (Lobby)',
          floor_type: 'lobby',
          access_level: 'public'
        });
      }

      // Create guest floors
      for (let i = 1; i <= config.total_floors; i++) {
        const exists = floors.some(f => f.floor_number === i);
        if (!exists) {
          floorsToCreate.push({
            floor_number: i,
            floor_name: `Floor ${i}`,
            floor_type: 'guest_rooms',
            total_rooms: 100,
            access_level: 'guest_only'
          });
        }
      }

      if (floorsToCreate.length === 0) {
        throw new Error('All floors already exist');
      }

      await db.entities.Floor.bulkCreate(floorsToCreate);
      return floorsToCreate.length;
    },
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: ['floors'] });
      toast.success(`${count} floors created!`);
    },
    onError: (error) => {
      toast.error(error.message);
    }
  });

  const createElevatorMutation = useMutation({
    mutationFn: (data) => db.entities.Elevator.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['elevators'] });
      setElevatorConfig({ elevator_name: '', capacity: 10 });
      toast.success('Elevator created!');
    }
  });

  const generateRoomsMutation = useMutation({
    mutationFn: async (config) => {
      const roomsToCreate = [];

      for (let floorNum = config.start_floor; floorNum <= config.end_floor; floorNum++) {
        const floor = floors.find(f => f.floor_number === floorNum);
        if (!floor || floor.floor_type !== 'guest_rooms') continue;

        for (let roomNum = 0; roomNum <= 99; roomNum++) {
          const roomNumber = `${floorNum}${roomNum.toString().padStart(2, '0')}`;

          const exists = rooms.some(r => r.room_number === roomNumber);
          if (!exists) {
            roomsToCreate.push({
              room_number: roomNumber,
              floor_id: floor.id,
              room_type: config.room_type,
              status: 'available',
              rate_per_night: config.rate_per_night,
              max_occupancy: config.room_type === 'penthouse' ? 6 : 
                             config.room_type === 'suite' ? 4 : 
                             config.room_type === 'deluxe' ? 3 : 2,
              amenities: []
            });
          }
        }
      }

      if (roomsToCreate.length === 0) {
        throw new Error('No new rooms to create. They may already exist.');
      }

      const batchSize = 50;
      for (let i = 0; i < roomsToCreate.length; i += batchSize) {
        const batch = roomsToCreate.slice(i, i + batchSize);
        await db.entities.Room.bulkCreate(batch);
      }

      return roomsToCreate.length;
    },
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: ['rooms'] });
      toast.success(`${count} rooms generated!`);
    },
    onError: (error) => {
      toast.error(error.message);
    }
  });

  const generateParkingMutation = usMutation({
    mutationFn: async (config) => {
      const parkingFloor = floors.find(f => f.floor_name.includes(config.level));
      if (!parkingFloor) {
        throw new Error(`Parking floor ${config.level} not found. Please create floors first.`);
      }

      const existingSpots = await db.entities.ParkingSpot.filter({ level: config.level });
      const spotsToCreate = [];

      for (let i = 1; i <= config.spots_per_level; i++) {
        const spotNumber = `${config.level}-${i.toString().padStart(3, '0')}`;
        const exists = existingSpots.some(s => s.spot_number === spotNumber);

        if (!exists) {
          spotsToCreate.push({
            spot_number: spotNumber,
            level: config.level,
            zone: i <= config.spots_per_level * 0.1 ? 'vip' : 
                  i <= config.spots_per_level * 0.15 ? 'electric' :
                  i <= config.spots_per_level * 0.2 ? 'handicap' : 'standard',
            status: 'available',
            rate_per_hour: 5,
            has_charging: i <= config.spots_per_level * 0.15
          });
        }
      }

      if (spotsToCreate.length === 0) {
        throw new Error('All parking spots already exist for this level');
      }

      const batchSize = 50;
      for (let i = 0; i < spotsToCreate.length; i += batchSize) {
        const batch = spotsToCreate.slice(i, i + batchSize);
        await db.entities.ParkingSpot.bulkCreate(batch);
      }

      return spotsToCreate.length;
    },
    onSuccess: (count) => {
      queryClient.invalidateQueries();
      toast.success(`${count} parking spots created!`);
    },
    onError: (error) => {
      toast.error(error.message);
    }
  });

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Settings className="w-6 h-6" />
            System Configuration
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="floors">
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="floors">Floors</TabsTrigger>
              <TabsTrigger value="elevators">Elevators</TabsTrigger>
              <TabsTrigger value="rooms">Rooms</TabsTrigger>
              <TabsTrigger value="parking">Parking</TabsTrigger>
            </TabsList>

            <TabsContent value="floors" className="space-y-4">
              <Card className="border-2 border-blue-200">
                <CardContent className="p-4 space-y-3">
                  <h3 className="font-semibold">Generate Building Floors</h3>
                  <p className="text-sm text-slate-600">Automatically create all floors for your hotel</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label>Number of Guest Floors</Label>
                      <Input
                        type="number"
                        min="1"
                        value={floorGenConfig.total_floors}
                        onChange={(e) => setFloorGenConfig({ ...floorGenConfig, total_floors: parseInt(e.target.value) })}
                      />
                      <p className="text-xs text-slate-500 mt-1">Floor 1 to {floorGenConfig.total_floors}</p>
                    </div>
                    <div>
                      <Label>Number of Parking Levels</Label>
                      <Input
                        type="number"
                        min="0"
                        value={floorGenConfig.parking_floors}
                        onChange={(e) => setFloorGenConfig({ ...floorGenConfig, parking_floors: parseInt(e.target.value) })}
                      />
                      <p className="text-xs text-slate-500 mt-1">P1 to P{floorGenConfig.parking_floors}</p>
                    </div>
                  </div>
                  <Button 
                    onClick={() => generateFloorsMutation.mutate(floorGenConfig)} 
                    className="w-full"
                    disabled={generateFloorsMutation.isPending}
                  >
                    {generateFloorsMutation.isPending ? 'Generating...' : 'Generate Floors'}
                  </Button>
                </CardContent>
              </Card>

              <div className="space-y-2">
                <h3 className="font-semibold">Existing Floors ({floors.length})</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {floors.sort((a, b) => b.floor_number - a.floor_number).map(floor => (
                    <Card key={floor.id}>
                      <CardContent className="p-3 text-center">
                        <Building2 className="w-6 h-6 mx-auto mb-2 text-blue-600" />
                        <p className="font-bold">Floor {floor.floor_number}</p>
                        <p className="text-xs text-slate-600">{floor.floor_name}</p>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            </TabsContent>

            <TabsContent value="elevators" className="space-y-4">
              <Card className="border-2 border-blue-200">
                <CardContent className="p-4 space-y-3">
                  <h3 className="font-semibold">Add New Elevator</h3>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label>Elevator Name</Label>
                      <Input
                        placeholder="e.g., Elevator A"
                        value={elevatorConfig.elevator_name}
                        onChange={(e) => setElevatorConfig({ ...elevatorConfig, elevator_name: e.target.value })}
                      />
                    </div>
                    <div>
                      <Label>Capacity</Label>
                      <Input
                        type="number"
                        value={elevatorConfig.capacity}
                        onChange={(e) => setElevatorConfig({ ...elevatorConfig, capacity: parseInt(e.target.value) })}
                      />
                    </div>
                  </div>
                  <Button onClick={() => createElevatorMutation.mutate({ ...elevatorConfig, status: 'idle', current_floor: 1 })} className="w-full">
                    Create Elevator
                  </Button>
                </CardContent>
              </Card>

              <div className="space-y-2">
                <h3 className="font-semibold">Existing Elevators ({elevators.length})</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {elevators.map(elevator => (
                    <Card key={elevator.id}>
                      <CardContent className="p-3 text-center">
                        <ArrowUpDown className="w-6 h-6 mx-auto mb-2 text-green-600" />
                        <p className="font-bold">{elevator.elevator_name}</p>
