              required
            />
          </div>

          <Button 
            type="submit" 
            className="w-full bg-blue-600 hover:bg-blue-700"
            disabled={lookupMutation.isPending}
          >
            {lookupMutation.isPending ? 'Looking up...' : 'Continue'}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

